/* Prototype gallery — renders SCREEN_GROUPS (generated by
   tools/build-manifest.mjs) as framed screen cards. */

(() => {
  const N = window.NEXA;
  // SCREEN_GROUPS / SCREEN_COUNT come from assets/screens.js as classic-script
  // `const` bindings, so they live in the global lexical scope and are NOT
  // reachable as window.SCREEN_GROUPS. Reference them by bare name, with a
  // guard in case the manifest has not been generated yet.
  const GROUPS = typeof SCREEN_GROUPS === 'undefined' ? [] : SCREEN_GROUPS;
  const COUNT = typeof SCREEN_COUNT === 'undefined' ? 0 : SCREEN_COUNT;

  const SURFACE_LABEL = {
    mobile: 'Mobile · Expo',
    auth: 'Auth',
    web: 'Web · Next.js',
    shell: 'Prototype',
  };

  const GROUP_NOTE = {
    Auth: 'Entry points for both surfaces. Validation is inline, success states navigate into the mobile inbox.',
    Mobile: 'The end-user surface: notifications, RSVP, calendar, countdowns, todos, and account.',
    'Web dashboard': 'The admin surface: broadcast and manage, read attendance statistics, build templates.',
    Prototype: 'Index and design-system reference for the review.',
  };

  /** One screen card, framed as a phone (430px) or a browser window (1440px).
   *  A screenshot that has not been generated yet falls back to a labelled
   *  placeholder rather than a broken image.
   *  Images load eagerly on purpose: the gallery is itself captured by
   *  tools/cdp-check.mjs, and `loading="lazy"` leaves every below-the-fold
   *  thumbnail blank in that screenshot. */
  function card(s) {
    const isPhone = s.w < 620;
    const shot = `<img src="${s.shot}" alt="${N.esc(s.title)} screenshot"
      onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'shot-missing',textContent:'Run tools/cdp-check.mjs to capture this screen'}))" />`;
    const frame = isPhone
      ? `<div class="screen-frame screen-frame-phone">
           <div class="screen-crop">${shot}</div>
         </div>`
      : `<div class="screen-frame screen-frame-browser">
           <div class="browser-bar">
             <span class="browser-dots"><span></span><span></span><span></span></span>
             <span class="browser-url">nexa.app/${s.file.replace(/\.html$/, '')}</span>
           </div>
           <div class="screen-crop">${shot}</div>
         </div>`;

    return `<a class="screen-card" href="${s.file}">
      ${frame}
      <div class="screen-meta">
        <div class="grow">
          <div class="screen-title">${N.esc(s.title)}</div>
          <p class="screen-desc">${N.esc(s.desc)}</p>
          <div class="screen-tags">
            <span class="tag">${SURFACE_LABEL[s.surface] ?? s.surface}</span>
            ${s.feature && s.feature !== '—' ? `<span class="tag tag-feature">${N.esc(s.feature)}</span>` : ''}
            <span class="tag">${s.w}×${s.h}</span>
          </div>
        </div>
        ${N.icon('chevronRight', { size: 18, cls: 'c-soft' })}
      </div>
    </a>`;
  }

  function section(group) {
    const mobile = group.screens.every((s) => s.w < 620);
    return `<section class="doc-section" id="group-${group.name.replace(/\s+/g, '-').toLowerCase()}">
      <div class="nx-container">
        <header>
          <div>
            <h2>${N.esc(group.name)}</h2>
            <p class="doc-note" style="margin-top:4px">${N.esc(GROUP_NOTE[group.name] ?? '')}</p>
          </div>
          <span class="badge badge-outline">${group.screens.length} screens</span>
        </header>
        <div class="screen-grid ${mobile ? 'screen-grid-mobile' : ''}">
          ${group.screens.map(card).join('')}
        </div>
      </div>
    </section>`;
  }

  function render() {
    const featureCount = new Set(
      GROUPS.flatMap((g) => g.screens.map((s) => s.feature)).filter((f) => f && f !== '—'),
    ).size;
    const total = COUNT || GROUPS.reduce((n, g) => n + g.screens.length, 0);

    N.$('[data-slot="shell"]').innerHTML = `
      <nav class="doc-nav">
        <a class="brand" href="index.html">
          <span class="brand-mark">N</span>
          <span class="brand-name">NEXA</span>
        </a>
        <div class="doc-nav-links">
          <a href="#group-auth">Auth</a>
          <a href="#group-mobile">Mobile</a>
          <a href="#group-web-dashboard">Web dashboard</a>
          <a href="styleguide.html">Design system</a>
          <a class="btn btn-primary btn-sm" href="m-notifications.html">Open the app</a>
        </div>
      </nav>

      <div class="nx-container doc-hero">
        <span class="badge badge-outline">${N.icon('sparkle', { size: 13 })} Prototype · HTML/CSS/JS · no build step</span>
        <h1 class="t-display-lg" style="margin-top:var(--space-md)">The whole NEXA system, on screen</h1>
        <p class="t-body c-body">
          Every feature from the roadmap — interactive notifications, event RSVP, recipient targeting,
          the unified calendar, todo-based scheduling, and countdowns — plus the auth flow and both
          surfaces. Interactions are live: confirm a notification, change an RSVP, tick a task, or
          filter a calendar and the state follows you across screens.
        </p>
        <p class="t-body c-muted" style="margin-top:var(--space-sm);max-width:70ch">
          This is the review artefact for the UI/UX freeze. Approve or correct it here, and the
          Next.js 15 web app and Expo mobile app get built against exactly these layouts and tokens.
        </p>

        <div class="doc-stats">
          <div class="doc-stat"><strong>${total}</strong><span>screens</span></div>
          <div class="doc-stat"><strong>6</strong><span>roadmap features</span></div>
          <div class="doc-stat"><strong>3</strong><span>surfaces</span></div>
          <div class="doc-stat"><strong>${featureCount}</strong><span>feature groups covered</span></div>
        </div>

        <div class="row wrap gap-sm" style="margin-top:var(--space-xl)">
          <a class="btn btn-primary" href="m-notifications.html">${N.icon('mobile', { size: 16 })} Start on mobile</a>
          <a class="btn btn-secondary" href="dashboard.html">${N.icon('monitor', { size: 16 })} Open the dashboard</a>
          <a class="btn btn-secondary" href="styleguide.html">${N.icon('sparkle', { size: 16 })} Design system</a>
        </div>
      </div>

      <div class="nx-container">
        <div class="contract-list" style="margin-bottom:var(--space-xl)">
          ${[
            ['Cream canvas everywhere', 'The var(--color-canvas) floor is the system contract — no cool grey, no dark mode inversion.'],
            ['Six saturated surfaces', 'Pink, teal, lavender, peach, ochre, cream cards. Never a seventh, never twice in a row.'],
            ['Display 500, body Inter', 'Headlines keep weight 500 with negative tracking; everything else is Inter.'],
            ['No heavy shadows', 'Depth comes from saturated colour on cream, plus a faint hover lift.'],
          ]
            .map(
              ([title, body]) => `<div class="contract contract-yes">
                ${N.icon('check', { size: 18 })}
                <span class="stack" style="gap:2px">
                  <strong class="t-title-sm">${title}</strong>
                  <span class="t-caption c-muted">${body}</span>
                </span>
              </div>`,
            )
            .join('')}
        </div>
      </div>

      ${GROUPS.map(section).join('')}

      <footer style="background-color:var(--color-surface-soft);padding:var(--space-xxl) 0">
        <div class="nx-container between wrap gap-md">
          <div class="stack" style="gap:4px">
            <strong class="t-title-sm">NEXA UI/UX prototype</strong>
            <span class="t-body-sm c-muted">Generated from DESIGN.md and @nexa/design-tokens. Regenerate screenshots with <code>node tools/cdp-check.mjs</code>.</span>
          </div>
          <div class="row wrap gap-sm">
            <a class="btn btn-secondary btn-sm" href="README.md">${N.icon('download', { size: 14 })} Demo guide</a>
            <a class="btn btn-secondary btn-sm" href="BUILD-SPEC.md">${N.icon('check', { size: 14 })} Build spec</a>
          </div>
        </div>
      </footer>`;
  }

  N.page('index', () => render());
})();
